import { mkdir, writeFile } from "node:fs/promises";
import { basename, join, resolve } from "node:path";

export interface InitOptions {
  /** Parent directory for the bundle (default: cwd). */
  dir?: string;
  /** Bundle directory name. */
  name: string;
}

export interface InitResult {
  bundlePath: string;
  created: string[];
}

export async function initBundle(options: InitOptions): Promise<InitResult> {
  const parent = resolve(options.dir ?? process.cwd());
  const bundlePath = join(parent, options.name);
  await mkdir(bundlePath, { recursive: true });

  const created: string[] = [];
  const files: Array<[string, string]> = [
    ["index.md", indexTemplate(options.name)],
    ["log.md", logTemplate()],
    ["concept.md", conceptTemplate(options.name)],
  ];

  for (const [fileName, content] of files) {
    const path = join(bundlePath, fileName);
    try {
      await writeFile(path, content, { encoding: "utf8", flag: "wx" });
      created.push(fileName);
    } catch (err: unknown) {
      if (
        typeof err === "object" &&
        err !== null &&
        "code" in err &&
        (err as NodeJS.ErrnoException).code === "EEXIST"
      ) {
        continue;
      }
      throw err;
    }
  }

  return { bundlePath, created };
}

function indexTemplate(name: string): string {
  return `---
okf_version: "0.2"
---

# ${name}

Progressive disclosure index for this OKF bundle.

## Concepts

* [Example concept](concept.md) - Sample concept document with full frontmatter

`;
}

function logTemplate(): string {
  const today = new Date().toISOString().slice(0, 10);
  return `# Bundle Update Log

## ${today}

- Bundle initialized with \`pi-okf init\`.

`;
}

function conceptTemplate(name: string): string {
  const title = humanize(name);
  const now = new Date().toISOString();
  return `---
type: Concept
title: ${title} example concept
description: A sample concept document scaffolded by pi-okf init.
tags:
  - example
generated:
  by: process:pi-okf
  at: "${now}"
---

# ${title} example concept

Replace this body with curated knowledge. Keep facts sourced; do not invent.

`;
}

function humanize(name: string): string {
  const base = basename(name);
  return base
    .replace(/[-_]+/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

export function formatInitResult(result: InitResult): string {
  if (result.created.length === 0) {
    return `Bundle already present at ${result.bundlePath} (no new files).`;
  }
  return `Initialized ${result.bundlePath}: created ${result.created.join(", ")}.`;
}
